import React, { useState } from 'react';
import { Grommet, Box, DataTable, Select } from 'grommet';

const data = [
  { date: '2023-10-01', severity: 'High', details: 'Issue 1' },
  { date: '2023-10-02', severity: 'Low', details: 'Issue 2' },
  { date: '2023-10-03', severity: 'Medium', details: 'Issue 3' },
];

const columns = [
  { property: 'date', header: 'Date' },
  { property: 'severity', header: 'Severity' },
  { property: 'details', header: 'Details' },
];

const groupByOptions = ['Date', 'Severity'];

const App = () => {
  const [groupBy, setGroupBy] = useState('');

  return (
    <Grommet>
      <Box pad="medium">
        <Select
          options={groupByOptions}
          value={groupBy}
          onChange={({ option }) => setGroupBy(option)}
          placeholder="Group by..."
        />
        <DataTable
          columns={columns}
          data={data}
          groupBy={groupBy.toLowerCase()}
        />
      </Box>
    </Grommet>
  );
};

export default App;
